"""Авторский источник лекций; учебные примеры используют условные данные."""
TOPICS=[]
def table(columns,rows,caption):return dict(type='comparison',columns=columns,rows=rows,caption=caption)
def network(nodes,edges,caption):return dict(type='network',nodes=[dict(id=i,title=t,text=d) for i,t,d in nodes],edges=[dict(from_=a,to=b,label=c) for a,b,c in edges],caption=caption)
def process(items,caption):return dict(type='process',items=[dict(title=a,text=b) for a,b in items],caption=caption)
def C(title,body,speech,notebook='',visual=None):
    d=dict(title=title,body=body,speech=speech)
    if notebook:d['notebook']=notebook
    if visual:
        if visual['type']=='network':
            for e in visual['edges']:e['from']=e.pop('from_')
        d['visual']=visual
    return d
def T(slug,semester,title,question,intro,contents,quiz,case,reading='architecture'):
    TOPICS.append(dict(slug=slug,semester=semester,title=title,question=question,intro=intro,contents=contents,quiz=quiz,case=case,reading=reading))
def V(title,given,steps,result,review,accepted):return dict(title=title,given=given,steps=steps,result=result,review=review,accepted=accepted)

T('system-boundary',5,'Информационная система как комплекс. Границы системы',
'Что включить в систему, чтобы отвечать за результат её работы?',
'На складе приложение доступно, но отпуск товара остановлен: нет сотрудника с правом подтверждения. Разберём, почему исправный сервер ещё не означает работоспособную информационную систему.',[
C('Информационная система и её назначение','ИС связывает данные, средства их обработки и действия людей ради конкретных функций. Для системы склада результат — зарегистрированное движение товара и достоверный остаток, а не только открытая форма.',
'Начнём с результата: кладовщик должен принять товар, сохранить документ и получить новый остаток. Компьютер обеспечивает выполнение операций, программа задаёт правила, данные описывают товар, сотрудник подтверждает факт приёмки. Если исключить человека и порядок подтверждения, технически доступное приложение позволит сохранить неподтверждённые сведения. Поэтому состав ИС определяется функцией, которую требуется выполнить. Одна и та же сеть может обслуживать несколько систем, но это не делает их функции одинаковыми.',
'Информационная система — совокупность данных, средств и процессов их обработки, обеспечивающая заданные информационные функции.'),
C('Пять видов обеспечения','Каждый вид обеспечения отвечает на свой вопрос: чем выполняем, по каким алгоритмам, с какими данными, в каком порядке и на каком основании.',
'Разделение помогает искать причину остановки. У отсутствующей накладной информационная причина; у сотрудника без роли — организационная или ошибка настройки полномочий. Правовое обеспечение задаёт допустимые основания обработки, договорные условия и права на программы и сведения. Оно связано с организационными правилами, но не сводится к ним: локальная инструкция сама по себе не создаёт право использовать чужой ресурс. Для конкретного внедрения основания проверяются по действующим документам организации.',visual=table(['Обеспечение','Складской пример'],[['Техническое','Терминал, сканер, сеть, сервер'],['Программное','Клиент, сервис учёта, СУБД'],['Информационное','Номенклатура, накладные, остатки'],['Организационное','Роли, приёмка, порядок исправления'],['Правовое','Лицензии, договоры, основания доступа']],'Виды обеспечения дополняют друг друга; строка таблицы не является отдельным этапом исполнения.')),
C('Граница и внешние участники','Граница фиксирует, за какие функции и компоненты отвечает рассматриваемая система. Поставщик, банк и внешняя почта остаются окружением; обмен с ними входит в описание интерфейсов.',
'Проведём границу вокруг учёта склада: внутри — справочник, документы, сервис, база и работа оператора. Поставщик присылает накладную, но его собственная система не становится частью нашего сопровождения. Канал обмена и правила проверки накладной необходимо описать, иначе ошибка поставщика окажется невидимой зависимостью. Граница ответственности может отличаться от физического размещения: арендуемый сервер размещён вне здания, а за конфигурацию приложения отвечает наша команда.',
'Граница системы — установленное отделение рассматриваемых функций и компонентов от их окружения.',
network([('supplier','Поставщик','Внешняя сторона'),('operator','Кладовщик','Работа по регламенту'),('app','Сервис склада','Проверка и проведение'),('db','База данных','Документы и остатки')],[('supplier','operator','Накладная'),('operator','app','Подтверждение приёмки'),('app','db','Запись движения')],'Учебная схема взаимодействия. Внутри границы: кладовщик в своей роли, сервис и данные; поставщик снаружи.')),
C('Разбор: сервер доступен, отпуск остановлен','Учебный случай: сеть работает, приложение отвечает, остаток доступен. Подтверждающая роль назначена только сотруднику в отпуске. Технические проверки проходят, производственная функция не выполняется.',
'Сопоставим наблюдения с функцией: чтение остатка проверено, подтверждение отпуска — нет. Замена сервера не восстановит полномочия. Нужен установленный порядок замещения с назначением разрешённой роли, затем контрольный отпуск учебного товара и проверка записи в журнале. Передавать личный пароль отсутствующего сотрудника не требуется. Этот случай показывает, почему завершение диагностики определяется сквозной операцией, а не последним ответом ping.',
'Работоспособность проверяют по требуемой функции и условиям её выполнения.')],
dict(prompt='Система получает платёжный статус из банка. Как описать банк в границах складской ИС?',options=['Внешний участник и интерфейс обмена','Внутренний модуль только потому, что есть API','Элемент технического обеспечения склада','Несущественная деталь без зависимости'],correct=0,explanation='Банк находится вне управления складской ИС. Интерфейс, формат статуса и действия при его недоступности описываются как внешняя зависимость.'),
dict(task='Укажите вид обеспечения, изменение которого непосредственно восстановит подтверждение: «организационное» или «техническое».',output='Введите одно слово и объясните, почему остальные наблюдения не подтверждают выполнение функции.',variants=[
V('Нет замещающей роли','Сервис отвечает; запись доступна; подтверждать может только отсутствующий сотрудник.',[('Проверка сервиса','Ответ получен'),('Проверка функции','Нет сотрудника с полномочием'),('Причина','Не определено замещение')],'Организационное','Нужно назначить замещающего по принятому порядку. После назначения проверить подтверждение и журнал операции. Смена оборудования не меняет полномочий.',['организационное']),
V('Нет питания терминала','Замещающий назначен; сервер работает; терминал приёмки не включается; проверенный блок питания восстанавливает включение.',[('Проверка роли','Замещающий имеет полномочие'),('Проверка терминала','Не включается'),('Проверка питания','С исправным блоком включается')],'Техническое','Наблюдения указывают на питание терминала. Замену выполняют в разрешённых границах, затем проверяют всю операцию; исправная роль не устраняет аппаратный дефект.',['техническое'])]),'systems')

T('structure',5,'Базовая структура информационной системы',
'Как рабочее место получает и сохраняет данные?',
'При сканировании товара участвуют несколько устройств. Проследим запрос и отличим вычисление, передачу, хранение и взаимодействие с физическим миром.',[
C('Устройства и их роли','Рабочее место принимает действия пользователя. Сеть передаёт сообщения. Сервер выполняет общие сервисы. Хранилище сохраняет данные. Периферия вводит или выводит физические сигналы.',
'Один корпус может совмещать роли: сервер способен содержать собственные диски, а рабочая станция — запускать локальную базу. На структурной схеме важно различать функцию и устройство. Сканер преобразует штрихкод во входные данные, но не подтверждает факт поступления товара. Дисковый массив хранит блоки; согласованность операций с этими блоками обеспечивает программный уровень. Сетевой коммутатор связывает порты локальной сети, а маршрутизатор связывает IP-сети.',
'Структура ИС — состав её компонентов и связи, необходимые для выполнения функций.'),
C('Маршрут обращения к данным','Пример: терминал отправляет код товара; сервис запрашивает запись; СУБД читает данные; ответ возвращается терминалу. После подтверждения приёмки отдельная операция изменяет остаток.',
'Чтение и изменение отделены специально. Найденная карточка товара ещё не означает, что приход зарегистрирован. Пройдём от терминала к сервису, затем к базе и обратно. Если ответ потерян после записи, повторное нажатие не должно создавать второй приход: идентификатор документа позволяет установить, была ли операция уже проведена. Даже в ознакомительной структурной схеме полезно подписать, какие данные идут по связи, иначе линии показывают только соседство коробок.',visual=network([('scanner','Сканер','Код товара'),('pc','Рабочее место','Форма приёмки'),('switch','Коммутатор','Локальная сеть'),('server','Сервер','Сервис и СУБД'),('store','Хранилище','Документы и журнал')],[('scanner','pc','Ввод кода'),('pc','switch','Запрос карточки'),('switch','server','Передача запроса'),('server','store','Чтение и запись')],'Функциональная схема; обратный ответ проходит по тому же сетевому пути.')),
C('Питание и общие зависимости','Два сервера за одним коммутатором и одним источником питания сохраняют общие точки отказа. RAID защищает от отдельных отказов дисков, но не заменяет независимую резервную копию.',
'Общая зависимость важнее количества одинаковых устройств. Отключение единственного коммутатора лишит оба сервера доступа, а удаление данных приложением повторится на всех дисках зеркала. Резервная копия имеет самостоятельную историю и проверяемое восстановление. Источник бесперебойного питания даёт время на переживание короткого сбоя или корректное завершение; его фактическая автономность зависит от нагрузки и состояния батареи.',
'Резервная копия — отдельная сохранённая версия данных, предназначенная для восстановления.'),
C('Разбор: сканер печатает символы, товар не найден','Учебные данные: код в справочнике «004281», сканер передаёт «4281». Клавиатура, сеть и сервер исправны. Причина — потеря ведущих нулей при преобразовании кода в число.',
'Вместо замены сканера сравним исходный код, строку ввода и ключ в справочнике. Ведущие нули входят в идентификатор, поэтому его хранят как строку и проверяют правила нормализации. Контрольный повтор с «004281» находит карточку. Теперь проверим второй код с ведущими нулями, чтобы исправление не было разовой подстановкой. Физическая структура подсказывает путь проверки, но окончательный вывод требует данных на границах компонентов.')],
dict(prompt='Какое наблюдение подтверждает сохранение прихода товара?',options=['Сканер издал звуковой сигнал','Появилась карточка товара','В базе есть проведённый документ и соответствующее изменение остатка','На коммутаторе горит индикатор'],correct=2,explanation='Звук, карточка и индикатор подтверждают отдельные звенья. Сохранение проверяется по документу и согласованному изменению данных.'),
dict(task='По наблюдениям выберите ближайший объект проверки: «приложение» или «сеть».',output='Введите один объект; в объяснении укажите границу, на которой появляется расхождение.',variants=[
V('Неверный код','Терминал доступен; сервис отвечает; в форме код 137 вместо 00137.',[('Исходник','00137'),('Форма','137'),('Сопоставление','Нули потеряны до поиска')],'Приложение','Проверяем преобразование строки и правила кода в приложении. Ответ сервиса показывает доступность пути, но не правильность идентификатора.',['приложение']),
V('Нет связи с сервисом','Терминал включён; после замены разрешённого патч-корда линк появляется и сервис открывается; настройки не менялись.',[('Исходник','Линк отсутствует'),('Замена кабеля','Линк появился'),('Сквозная операция','Сервис открылся')],'Сеть','Проверка заменой локализовала проблему в кабельном участке сети. После замены проверяется операция, а результат не распространяется на все кабели.',['сеть'])]))

T('classification',5,'Классификация информационных систем',
'Как описать одну систему по нескольким независимым основаниям?',
'Облачная система может быть учётной и корпоративной одновременно. Разберём признаки, чтобы сравнение систем не смешивало назначение с размещением.',[
C('Три оси классификации','По назначению различают учётные, управляющие, аналитические, справочные и другие ИС. Масштаб описывает охват пользователей и подразделений. Размещение показывает, где выполняются сервисы и хранятся данные.',
'Это разные вопросы. Назначение отвечает, какую работу поддерживает система; масштаб — кого и какие процессы она охватывает; размещение — где находятся вычисления и данные. Классификации учебные: реальные решения часто совмещают функции. Важно назвать основание и объяснить признаки, а не подобрать единственный ярлык для всей системы. Термин «корпоративная» не задаёт точного числа пользователей без принятого в задаче определения.',
'Классификация — распределение объектов по явно выбранным признакам.'),
C('Матрица признаков','Учебное предприятие использует общую систему снабжения в двух филиалах. Сервис размещён у поставщика, складские терминалы стоят локально.',
'Назначение определяем по операциям закупки, поступления и остатков. Масштаб — по охвату нескольких подразделений с общими справочниками и правами. Размещение центрального сервиса — внешнее, но терминалы остаются на местах; это не противоречие. Облачное предоставление сервиса не гарантирует доступность при потере Интернета и не отменяет обязанности организации проверить выгрузку и восстановление данных.',visual=table(['Основание','Признак','Что требуется проверить'],[['Назначение','Учёт и снабжение','Документы, остатки, закупки'],['Масштаб','Несколько филиалов','Разделение прав и общие данные'],['Размещение','Сервис у поставщика','Канал, договор, выгрузка, восстановление']],'Один объект получает характеристику по каждой оси.')),
C('Локальное, облачное и гибридное размещение','Локальное размещение требует сопровождать собственную инфраструктуру. В облаке часть инфраструктуры обслуживает поставщик. Гибрид объединяет части с разными местами размещения и явными каналами обмена.',
'Распределение работ следует из конкретной модели услуги: аренда виртуальной машины и готовое прикладное приложение передают поставщику разный объём обязанностей. Поэтому «облако» нельзя считать готовым ответом о резервном копировании. В гибриде отдельно описывают, какая сторона является источником каждой записи, как передаются изменения и что происходит при разрыве связи. Копия без правил согласования создаёт две расходящиеся версии данных.'),
C('Разбор: ограничение меняет выбор','Учебные условия: в удалённом складе канал пропадает на два часа; отпуск должен продолжаться. Вариант с обязательным подтверждением каждой операции центральным облачным сервисом условию не отвечает.',
'Сначала применяем обязательное ограничение, затем сравниваем стоимость и удобство оставшихся вариантов. Возможны локальный сервис или предусмотренная автономная очередь с последующим согласованием. Слово «автономный» нужно раскрыть: допустимые операции, локальные данные, уникальность номеров, действия при конфликте остатков. Наличие красивого интерфейса или низкой цены не компенсирует отсутствие требуемой функции.')],
dict(prompt='Какое описание использует независимые основания классификации?',options=['Облачная, поэтому только аналитическая','Учётная по назначению, корпоративная по охвату, облачная по размещению','Большая, значит обязательно локальная','Справочная, следовательно однопользовательская'],correct=1,explanation='Назначение, масштаб и размещение описывают разные свойства; ни одно из них автоматически не определяет остальные.'),
dict(task='Какой вариант проходит обязательное условие работы при разрыве канала: A или B?',output='Введите A или B. Цена учитывается только после проверки обязательных условий.',variants=[
V('Нужна автономность','A: 20 условных единиц, без автономности. B: 35 единиц, автономный отпуск с регламентом обмена. Разрыв канала 2 ч допустим только без остановки отпуска.',[('Ограничение','Отпуск при разрыве канала'),('A','Не проходит'),('B','Проходит при проверенном обмене')],'B','A исключается независимо от цены. Для B проверяют автономные операции и разрешение конфликтов. Условные цены не являются рыночным предложением.',['b','B']),
V('Остановка допустима','A и B выполняют все обязательные функции. Автономность не требуется. Единственный критерий среди допустимых — меньшая стоимость: A=20, B=35.',[('Ограничения','Оба прошли'),('Критерий','Минимум стоимости'),('Сравнение','20 < 35')],'A','При изменённом условии нельзя автоматически сохранить прежний выбор B. По заданному единственному критерию выбирается A.',['a','A'])]),'systems')

T('accounting-supply',5,'Информационные системы учёта и материально-технического снабжения',
'Как документы превращаются в остатки и решение о закупке?',
'Один товар может быть физически на складе, уже обещан клиенту и ещё не списан. Разделим фактический остаток, резерв и доступное количество.',[
C('Назначение и состав','Учётная ИС регистрирует хозяйственные факты. Система снабжения связывает потребность, заказ поставщику, поступление и обеспечение подразделений. Общие данные: номенклатура, единицы, склады, контрагенты и документы.',
'Документ задаёт основание движения, а проведение изменяет учётные регистры по принятому правилу. Потребность в снабжении появляется из плана, заявки или уровня запаса. Если в справочнике один товар заведён дважды, отчёт покажет два разных остатка; исправная сеть эту ошибку не обнаружит. Состав включает рабочие места закупщика и кладовщика, сервис, базу, средства идентификации и обмена с другими системами.',
'Материально-техническое снабжение — обеспечение деятельности необходимыми материальными ресурсами в нужном количестве и сроке.'),
C('Цепочка снабжения','Учебный процесс: заявка подразделения → согласованный заказ → поступление → размещение → отпуск. Заказ поставщику ещё не увеличивает физический остаток.',
'На каждой связи меняется состояние обязательства или ресурса. Заявка выражает потребность, заказ — договорённость о поставке, приход подтверждает получение. Изменение статуса заказа без складского документа не является поступлением. Идентификатор поставки связывает записи и предотвращает повторное проведение при повторной передаче. Проверка эксплуатации должна пройти цепочку и обнаружить потерянный переход, а не только наличие отдельных форм.',visual=process([('Потребность','Заявка и требуемая дата'),('Заказ','Поставщик и подтверждение'),('Поступление','Количество и расхождения'),('Отпуск','Получатель и основание')],'Этапы читаются по номерам: потребность, заказ, поступление, отпуск. Возвраты оформляются отдельными документами.')),
C('Остаток, резерв и потребность','Учебное правило: доступно = остаток − резерв. К заказу = max(0, потребность + целевой запас − доступно − подтверждённые ожидаемые поступления). Учитываются только поставки, успевающие к требуемой дате.',
'В формуле нельзя дважды вычесть одно и то же обязательство. В нашем примере потребность — новая потребность сверх уже учтённого резерва. Сначала приводим единицы к одному виду, затем считаем доступное. Ожидаемая поставка уменьшает закупку только при подтверждённом количестве и подходящей дате. Эта формула является правилом учебного случая: реальные системы используют более подробные политики запасов, сроков и партий.',
'Доступный остаток = фактический учётный остаток − зарезервированное количество.'),
C('Разбор: расчёт закупки','Учебные данные: остаток 120 шт., резерв 30 шт., новая потребность 100 шт., целевой запас 20 шт., подтверждённая поставка 10 шт. до даты потребности. Доступно 90 шт.; заказать max(0, 100 + 20 − 90 − 10) = 20 шт.',
'Укажем единицы: все величины в штуках одного товара. Резерв уже уменьшил остаток до 90, поэтому повторно прибавлять его в потребность нельзя. Поставка 10 учитывается до нужной даты; если она опоздает, закупка в этом расчёте станет 30. Для проверки эксплуатации сравниваем расчёт с исходными документами, статусами резервов и датами; один итог отчёта без этих оснований не доказывает правильность.'),
C('Особенности эксплуатации','Контролируют единицы и дубли справочников, последовательность проведения, отрицательные остатки, обмен и журнал изменений. Исправление факта выполняют документом корректировки по принятому порядку.',
'Сканер, этикетка и терминал зависят от соответствия кода справочнику. После восстановления из копии нужно сверить документы, прошедшие на смежной стороне обмена: повторная загрузка способна создать дубли. Для отказа канала заранее задают допустимые действия, чтобы бумажные накладные и последующий ввод имели проверяемое соответствие. Удаление проведённых записей напрямую лишает систему истории оснований.')],
dict(prompt='Какое событие увеличивает учётный складской остаток в описанном процессе?',options=['Создание заявки','Подтверждение заказа поставщиком','Проведение фактически проверенного поступления','Отправка письма поставщику'],correct=2,explanation='Заказ и заявка описывают потребность и обязательство. В принятой модели движение появляется при проведении документа поступления.'),
dict(task='Рассчитайте количество к заказу по правилу лекции. Резерв уже учтён; потребность новая.',output='Введите количество в штуках без единицы.',variants=[
V('Поставка вовремя','Остаток 80, резерв 20, новая потребность 90, целевой запас 10; подтверждённая поставка 15 успевает.',[('Доступно','80 − 20 = 60 шт.'),('Дефицит с запасом','90 + 10 − 60 = 40 шт.'),('Учёт поставки','40 − 15 = 25 шт.')],'25','Доступно 60. Требуется 100 с целевым запасом. Вычитаем 60 и подтверждённые 15: к заказу 25 шт.',['25']),
V('Поставка опоздала','Те же данные: 80, 20, 90 и 10. Поставка 15 придёт после даты потребности.',[('Доступно','80 − 20 = 60 шт.'),('Поставка','Не учитывается к нужной дате'),('Дефицит','90 + 10 − 60 = 40 шт.')],'40','Позднее поступление не покрывает потребность к заданному сроку. По условиям этого расчёта требуется 40 шт.; возможный перенос даты согласуют отдельно.',['40'])]),'systems')

T('production-quality',5,'Информационные системы управления производством и качеством',
'Как связать план, исполнение и доказательство качества партии?',
'Готовая деталь без записи о партии и результатах контроля не даёт возможности установить, из какого сырья она изготовлена. Проследим данные производства.',[
C('Планирование, исполнение и контроль','Планирование определяет потребность и сроки. Производственное исполнение фиксирует операции, оборудование и фактический выпуск. Контроль качества связывает измерения, критерии и решение о годности.',
'В учебной модели ERP связывает ресурсы предприятия, MES — ход исполнения, а QMS — процессы качества; границы функций конкретного продукта могут различаться. Названия классов не гарантируют наличия нужного модуля. Для выбора и эксплуатации проверяют, откуда приходит задание, кто фиксирует факт операции и чем подтверждается результат контроля. Запись «готово» без измерения не равна записи «соответствует требованиям».',
'Прослеживаемость — возможность восстановить историю и связи объекта по идентифицированным записям.'),
C('Связь партии с операциями','Учебная партия P-17 изготовлена из сырья R-05 на оборудовании M-02. Контроль Q-31 относится к этой партии и принятой редакции требований.',
'Связи нужны для практического вопроса: какие изделия затронуты, если сырьё R-05 признано несоответствующим? Система должна найти все партии, потребившие это сырьё, и их последующие отгрузки. Потерянный идентификатор превращает точечную проверку в проверку всего выпуска. Время операции и идентификатор оборудования дополняют связь, но не заменяют её; совпавшая дата ещё не доказывает использование одной партии.',visual=network([('raw','R-05','Партия сырья'),('order','P-17','Производственная партия'),('machine','M-02','Оборудование'),('test','Q-31','Результаты контроля'),('ship','Отгрузка','Получатель партии')],[('raw','order','Израсходовано в'),('machine','order','Операция на'),('order','test','Проверена по'),('order','ship','Включена в')],'Свободная схема прослеживаемости; связь обозначает документированный факт.')),
C('Измерение и решение о годности','Учебный допуск диаметра: 9,90–10,10 мм включительно. Измерение 10,08 мм соответствует числовому допуску. Для решения о партии дополнительно нужны правило выборки, пригодность средства измерения и идентичность объекта.',
'Числовое сравнение отвечает только на один вопрос о конкретном измеренном экземпляре. Нельзя распространить его на всю партию, если не задан план контроля. Если единицы в системе указаны неверно, корректная арифметика даст неверное решение. Сохраняют значение, единицу, время, оператора, средство измерения и правило оценки. Для пограничного результата в реальной задаче учитывают принятую процедуру и неопределённость измерения.',
'Соответствие — выполнение установленных требований, подтверждённое применимыми свидетельствами.'),
C('Разбор: несоответствие в партии','Учебные результаты одного изделия: 9,96; 10,04; 10,14 мм, допуск 9,90–10,10 мм. Третье значение за пределом. В принятом учебном правиле «любое нарушение блокирует выпуск» партия переводится на разбор.',
'Сначала проверим идентификацию изделия, затем единицы и редакцию допуска. Значение 10,14 больше 10,10, поэтому по заданному правилу выпуск блокируется. Среднее 10,0467 попадает в интервал, но не отменяет нарушения отдельного измерения. В эксплуатации проверяют, что блокировка действительно не допускает отгрузку, а исправление результата оставляет историю. Разблокирование требует предусмотренного решения, а не замены неудобного числа.'),
C('Особенности эксплуатации','Проверяют обмен с оборудованием, время и идентификацию партий, версии маршрутов, единицы измерений, действия при остановке линии и права на изменение результата контроля.',
'Для производственной системы важно согласовать обслуживание с технологическим процессом. Перезапуск сервиса во время операции может потерять незавершённый факт. Сначала устанавливают безопасное для процесса состояние и порядок восстановления. Контрольный набор должен содержать годный, негодный и граничный результат; только годный образец не проверяет запрет выпуска.')],
dict(prompt='Измерения: 9,96; 10,04; 10,14 мм. Допуск 9,90–10,10 мм. Правило: любое нарушение блокирует выпуск. Что делать?',options=['Принять по среднему','Блокировать выпуск и зарегистрировать несоответствие','Округлить 10,14 до 10','Удалить третье измерение'],correct=1,explanation='10,14 > 10,10. Правило относится к каждому результату, поэтому среднее и округление не устраняют несоответствие.'),
dict(task='По учебному правилу оцените одно измерение: «соответствует» или «не соответствует». Допуск включает обе границы; погрешность в этой задаче не моделируется.',output='Введите решение словами.',variants=[
V('На границе','Измерение 10,10 мм; интервал 9,90–10,10 мм включительно.',[('Нижняя граница','10,10 ≥ 9,90'),('Верхняя граница','10,10 ≤ 10,10'),('Вывод','Оба сравнения выполнены')],'Соответствует','Включительная граница допускает равенство. Это решение об одном измерении, а не вывод о всей партии.',['соответствует']),
V('За границей','Измерение 10,11 мм; тот же интервал 9,90–10,10 мм включительно.',[('Нижняя граница','10,11 ≥ 9,90'),('Верхняя граница','10,11 > 10,10'),('Вывод','Верхнее ограничение нарушено')],'Не соответствует','Изменение на 0,01 мм переводит результат за верхнюю границу. Самовольное округление для принятия результата не задано.',['не соответствует'])]),'quality')

T('reference-library',5,'Справочно-информационные и библиотечные системы',
'Чем поиск описания отличается от выдачи конкретного экземпляра?',
'В каталоге найдена книга, но ни одного экземпляра для выдачи нет. Это не обязательно ошибка: описание издания и физический экземпляр имеют разные состояния.',[
C('Назначение и состав','Справочная ИС хранит и выдаёт сведения по запросу. Библиотечная система дополнительно ведёт экземпляры, читателей, выдачи, возвраты, ограничения и комплектование.',
'Каталог описывает издание: автора, название, год и другие признаки. Экземпляр описывает конкретную единицу фонда со своим инвентарным номером или штрихкодом. Один каталогический объект может иметь несколько экземпляров с разным местом и состоянием. Поиск отвечает на вопрос «что описано», а выдача — «можно ли передать этот экземпляр этому читателю сейчас».',
'Экземпляр — отдельная учётная единица фонда, связанная с библиографическим описанием.'),
C('От поиска к выдаче','Учебное издание B-10 имеет E-101 в читальном зале и E-102 на руках. Поиск находит B-10; допустимость выдачи проверяется для выбранного экземпляра и читателя.',
'Справочные поля участвуют в поисковом индексе, а статус экземпляра — в операции обращения. Если описание переиндексировано с задержкой, поиск может не показать новую запись, хотя она существует. Если экземпляр выдан, его описание не должно исчезать из каталога. В эксплуатации различают полноту индекса, доступность карточки и целостность связей выдачи.',visual=table(['Объект','Идентификатор','Состояние'],[['Описание','B-10','Найдено по названию'],['Экземпляр','E-101','Только читальный зал'],['Экземпляр','E-102','Выдан читателю'],['Операция','Новая выдача','Нет доступного на абонементе экземпляра']],'Наличие описания не гарантирует доступность выдачи.')),
C('Состояния и ограничения','Перед выдачей проверяют идентификаторы, статус экземпляра, право читателя, ограничения и срок. Возврат завершает существующую выдачу; повторная выдача требует новой операции.',
'Баркод связывает сканирование с экземпляром, а не с абстрактным названием книги. Неверное соответствие способно изменить историю другого экземпляра. После сбоя нужно проверить, сохранилась ли операция, прежде чем повторять её. Сведения о читателях открываются по полномочиям; публичный каталог обычно не должен показывать, кто держит конкретную книгу. Правила доступа и сроки определяются организацией.'),
C('Разбор: карточка есть, поиск не находит','Учебное наблюдение: новая запись открывается по прямому идентификатору; поиск по точно указанному названию её не выдаёт; старые записи находятся. Проверяем включение записи в индекс и очередь индексирования.',
'Наблюдения локализуют различие между чтением записи и поисковым представлением. Они ещё не доказывают, что индекс повреждён: причиной могут быть фильтр филиала, поле поиска или задержка очереди. Сначала повторим запрос без лишнего фильтра, сверим поле и время обновления. При подтверждённой задержке выполняют предусмотренное обслуживание индекса, затем проверяют точный запрос и другой признак этой же записи.'),
C('Особенности эксплуатации','Контролируют резервное копирование каталога и выдач, очереди обмена, целостность связей экземпляров, поиск с разными полями, работу сканеров и разграничение публичного и служебного интерфейса.',
'Копия только библиографических описаний не восстанавливает обязательства читателей. После учебного восстановления сопоставляют число экземпляров, активные выдачи и тестовый возврат. Не следует проверять реальные операции на настоящих читателях без принятого порядка: для занятия достаточно вымышленных записей и выделенного учебного фонда.')],
dict(prompt='Поиск нашёл издание. Какое условие ещё необходимо для обычной выдачи?',options=['Наличие доступного экземпляра и разрешение по правилам читателя','Любое совпадение названия','Картинка обложки','Только ответ сервера'],correct=0,explanation='Описание издания не является конкретным экземпляром. Выдача проверяет экземпляр, читателя и действующие ограничения.'),
dict(task='Сколько экземпляров доступно для выдачи на абонементе по указанным состояниям?',output='Введите целое число. Экземпляры читального зала не выдаются на абонементе.',variants=[
V('Один свободен','E-1: свободен на абонементе; E-2: выдан; E-3: только читальный зал.',[('E-1','Учитываем: 1'),('E-2','Не учитываем: выдан'),('E-3','Не учитываем: ограничение')],'1','Подходит только E-1. Число описаний и число физических единиц не равно числу доступных для выбранного вида обслуживания.',['1']),
V('Возврат принят','E-1 свободен; E-2 возвращён и доступен на абонементе; E-3 только читальный зал.',[('E-1','Учитываем: 1'),('E-2','Учитываем: ещё 1'),('E-3','Не учитываем: ограничение')],'2','После завершённого возврата E-2 доступен; вместе с E-1 получаем 2. Само обещание читателя вернуть книгу не меняло бы состояние.',['2'])]),'library')

T('building-media',5,'Системы управления зданием и многозонным мультимедийным пространством',
'Как команды, измерения и медиасигналы проходят между зонами?',
'В аудитории работает изображение, но пропал звук. В соседней зоне всё исправно. Составим раздельные пути управления и медиасигналов.',[
C('Контур управления зданием','Датчик измеряет величину, контроллер выполняет правило, исполнительное устройство воздействует на объект. Система диспетчеризации отображает состояния, события и команды.',
'Например, датчик температуры передаёт измерение контроллеру, а тот управляет приводом по заданному правилу. Экран диспетчера не обязан быть элементом замкнутого контура: при его недоступности локальный контроллер может продолжать работу, если это предусмотрено проектом. Нужно различать текущее измерение и последнее сохранённое значение: устаревшие 22 градуса не доказывают, что в помещении сейчас та же температура.',
'Контур управления — связанные измерение, выработка управляющего воздействия и изменение объекта.'),
C('Состав многозонной медиасистемы','Источник формирует видео и звук; матрица или сетевое медиаустройство распределяет их; дисплей и акустика воспроизводят; контроллер выбирает маршруты и режимы зон.',
'Зона — помещение или группа устройств с самостоятельным назначением сигнала и уровня. Сигнал и команда могут идти разными путями: успешная команда включения дисплея не подтверждает доставку видеопотока. В сетевой системе отдельно описывают требования медиатрафика и управления. Общая сеть не превращает все устройства в взаимозаменяемые: проверяют протокол, формат, задержку и поддерживаемую конфигурацию.',visual=network([('source','Источник','Видео и звук'),('matrix','Матрица / DSP','Маршрутизация'),('display','Дисплей зоны A','Изображение'),('amp','Усилитель','Звук зоны A'),('ctrl','Контроллер','Команды выбора'),('sensor','Датчик','Состояние зоны')],[('source','matrix','Медиасигнал'),('matrix','display','Видео'),('matrix','amp','Аудио'),('ctrl','matrix','Выбор маршрута'),('sensor','ctrl','Измерение')],'Медиасигналы, команды и измерения подписаны отдельно.')),
C('Зоны, приоритеты и безопасные пределы','Для каждой зоны задают источник, выход, разрешённый уровень и права управления. Приоритеты оповещения и действия при отказах определяются проектом; учебная медиасистема не заменяет систему безопасности.',
'Отдельная зона позволяет включить показ в аудитории и сохранить другой источник в холле. Общий усилитель или неверная привязка выходов может нарушить это разделение. Во время проверки сначала устанавливают безопасный уровень громкости и учебный сигнал, затем проверяют одну зону. Изменения контуров инженерных и противопожарных систем без специального задания и допуска не входят в обычную диагностику мультимедиа.'),
C('Разбор: звук пропал только в зоне A','Учебные данные: изображение есть; индикатор аудио на входе DSP активен; на выходе A нет уровня; выход B работает. Для A включён mute. После разрешённого снятия mute на малом уровне слышен тестовый сигнал.',
'Проверка отсекла источник: на входе звук наблюдается. Исправность B подтверждает работу другой ветви, но не кабеля и усилителя A. Отсутствие уровня на выходе A вместе с включённым mute объясняет остановку до усилителя. После изменения выполняем конечную проверку в нужной зоне, затем возвращаем штатный источник и сохраняем предусмотренную конфигурацию. Из этого случая не следует, что всякая тишина вызвана mute.'),
C('Особенности эксплуатации','Проверяют время событий, актуальность измерений, состояния контроллеров, привязку зон, маршруты сигналов, сохранность конфигурации и восстановление после разрешённого перезапуска.',
'Для здания важен ещё режим ручного управления: кто имеет право вмешаться и как вернуться к автоматическому. Для мультимедиа проверяют, что после включения питания восстанавливается нужный маршрут, а не случайный последний вход. Наблюдение подтверждают в конечной точке: звук слышен в нужной зоне, изображение видно на нужном дисплее, измерение имеет свежую отметку времени.')],
dict(prompt='Контроллер подтвердил команду включения дисплея. Что это доказывает?',options=['Только обработку команды в пределах полученного подтверждения','Появление изображения любого формата','Исправность всех аудиозон','Актуальность каждого датчика'],correct=0,explanation='Команда и медиасигнал — разные пути. Изображение и звук проверяют в конечной точке; подтверждение не охватывает все устройства.'),
dict(task='Выберите ближайший узел проверки: «маршрут» или «источник».',output='Введите одно слово; схема сигнала остаётся той же.',variants=[
V('Вход есть, выход молчит','На входе DSP аудиоуровень есть. Выход B работает. На выходе A mute включён.',[('Источник','Сигнал есть на входе'),('Ветка B','Работает'),('Ветка A','Mute включён')],'Маршрут','Сначала проверить mute и назначение выхода A, затем сигнал после разрешённой коррекции. Источник уже наблюдается на входе.',['маршрут']),
V('Входы молчат','На выходах A и B звука нет; на входе DSP уровень отсутствует; источник остановлен.',[('Выходы','Оба молчат'),('Вход DSP','Сигнала нет'),('Источник','Воспроизведение остановлено')],'Источник','Сначала восстановить учебное воспроизведение на источнике и проверить вход DSP. Изменение выходных маршрутов не создаёт отсутствующий входной сигнал.',['источник'])]),'building')

T('integration',5,'Оборудование системной интеграции. Схема подключения',
'Как по схеме отличить путь сигнала, управления и питания?',
'Разъём подходит физически, но сигнал не появляется. Для соединения важны направление, формат, электрические условия и роль устройства.',[
C('Группы оборудования','Коммутационное оборудование выбирает и передаёт сигналы. Отображающее выводит изображение. Звуковое обрабатывает и воспроизводит аудио. Видеонаблюдение формирует, передаёт, записывает и просматривает изображение.',
'Слово «коммутатор» встречается в разных системах. Ethernet-коммутатор передаёт сетевые кадры, видеоматрица выбирает входы и выходы медиасигнала. Они не заменяют друг друга. Камера без регистратора может давать живой просмотр, но не выполнять требование архивной записи. Усилитель предназначен для согласованной нагрузки; его выход нельзя считать обычным линейным входом другого устройства.',
'Схема подключения — описание соединяемых портов, направлений, типов сигналов и необходимых условий соединения.'),
C('Учебная схема подключения','Камера передаёт IP-поток в PoE-коммутатор, регистратор получает поток и пишет архив. Рабочее место обращается к регистратору. Отдельная HDMI-линия связывает источник и дисплей.',
'На схеме подписаны конкретные роли портов. PoE возможно только при совместимости устройства, порта и энергетического бюджета. Наличие Ethernet-линии само по себе питание не обещает. HDMI и сеть изображены раздельно, чтобы не возникало ложного вывода, будто любая сеть напрямую подаст изображение в HDMI-вход. Для преобразования нужен соответствующий приёмник или декодер.',visual=network([('cam','IP-камера','Ethernet + совместимый PoE'),('sw','PoE-коммутатор','Передача и питание'),('nvr','Регистратор','Запись архива'),('pc','Рабочее место','Просмотр'),('src','Медиаисточник','HDMI OUT'),('screen','Дисплей','HDMI IN')],[('cam','sw','IP-видео'),('sw','cam','Питание PoE'),('sw','nvr','IP-поток'),('pc','sw','Запрос к регистратору'),('src','screen','HDMI-видео и аудио')],'Учебная схема двух трактов; источник питания коммутатора и регистратора проверяется отдельно.')),
C('Совместимость и схема портов','В перечне соединений указывают устройство, порт-источник, порт-приёмник, кабель, сигнал и условия. Для длинных линий учитывают допустимые параметры конкретного оборудования, а не универсальную длину для любого кабеля.',
'Начинаем с направления OUT→IN и поддерживаемого формата. Пассивный кабель с подходящими разъёмами не всегда преобразует протокол или направление. Для звука дополнительно учитывают уровень, балансность, нагрузку и усиление. Для IP-видео — адресацию, полномочия, кодек и режим записи. Проверка по заведомо исправному короткому тракту помогает отделить согласование устройств от проблемы длинной линии.'),
C('Разбор: расчёт PoE-бюджета','Учебные данные: четыре камеры требуют не более 12 Вт каждая на выходах коммутатора; доступный бюджет — 45 Вт. Требуется 48 Вт: конфигурация не проходит по суммарному бюджету, даже если все порты поддерживают PoE.',
'Считаем максимальные значения в одном месте измерения, включая оговорённые потребности устройств; 4×12=48. Предел 45 меньше 48, поэтому факт кратковременного включения камер не доказывает устойчивость в максимальном режиме. Нужен подходящий бюджет или другой предусмотренный способ питания. Отдельно проверяют лимит каждого порта. Реальные значения берут из спецификаций, учитывая подсветку, нагрев и потери в принятой модели.'),
C('Проверка отображения и записи','Для дисплея проверяют питание, вход, формат, кабель и источник. Для видеонаблюдения — живой поток, время, режим записи, накопитель, воспроизведение известного интервала и экспорт по полномочиям.',
'Живой просмотр и запись — две функции. Чтобы проверить архив, создаём учебное событие, фиксируем время, ждём завершения интервала и воспроизводим его с регистратора. Открытая картинка камеры не доказывает наличия архива. Рабочую конфигурацию фиксируют до изменений; после проверки возвращают согласованные параметры. Запись людей и доступ к архиву выполняются по установленным основаниям и правилам организации.')],
dict(prompt='Камера показывает живое видео. Что отдельно подтверждает архивную запись?',options=['Индикатор питания','Воспроизведение известного записанного интервала с правильным временем','Ответ ping','Наличие видеокабеля'],correct=1,explanation='Живой поток не доказывает работу накопителя, расписания и записи. Проверяется воспроизведение конкретного интервала.'),
dict(task='Сколько ватт суммарного PoE-бюджета требуется по условию?',output='Введите целое число. Потребность задана на выходах коммутатора, дополнительные потери не добавляйте.',variants=[
V('Четыре камеры','4 камеры по 11 Вт, бюджет 50 Вт; порт допускает 15 Вт.',[('Один порт','11 ≤ 15 Вт'),('Сумма','4 × 11 = 44 Вт'),('Бюджет','44 ≤ 50 Вт')],'44','По сумме и каждому порту конфигурация проходит заданные пределы. Запас 6 Вт не заменяет проверку реальной спецификации.',['44']),
V('Пять камер','5 камер по 11 Вт, бюджет 50 Вт; порт допускает 15 Вт.',[('Один порт','11 ≤ 15 Вт'),('Сумма','5 × 11 = 55 Вт'),('Бюджет','55 > 50 Вт')],'55','Каждый порт проходит, но суммарный бюджет превышен на 5 Вт. Число портов и общий ресурс питания — разные ограничения.',['55'])]),'video')

T('lan',5,'Локальная сеть информационной системы',
'Как последовательно проверить связность, адресацию и прикладной доступ?',
'Сервер отвечает по адресу, но приложение не открывается по имени. Разделим физическую линию, IP, разрешение имён и прикладной сервис.',[
C('Топология и активное оборудование','В звезде рабочие места подключены к коммутатору. Маршрутизатор передаёт пакеты между IP-сетями. Точка доступа соединяет беспроводных клиентов с сетью. VLAN разделяет логические сегменты при поддерживаемой конфигурации.',
'Физическая топология описывает соединения кабелей и устройств, логическая — доступные пути и разделение трафика. Сбой центрального коммутатора звезды влияет на подключённых клиентов; обрыв одного кабеля обычно затрагивает один участок. Петли и резервные связи требуют корректного протокола, поэтому для обычной проверки нельзя произвольно соединять два свободных порта. Адресация не исправляет отсутствие питания или линка.',
'Топология сети — схема связей узлов на выбранном физическом или логическом уровне.'),
C('IP-адрес, префикс, шлюз и DNS','Учебная подсеть 192.168.10.0/24: сервер 192.168.10.20, рабочее место 192.168.10.50, шлюз 192.168.10.1. DNS преобразует имя сервиса в адрес; шлюз нужен для пути за пределы локальной подсети.',
'При маске /24 первые 24 бита задают сеть. Адрес .0 — адрес сети, .255 — широковещательный в этой обычной подсети; для узлов используются .1–.254. Это правило нельзя механически переносить на любые префиксы. Для обращения .50 к .20 в том же сегменте внешний шлюз не является необходимым звеном маршрута. DNS — отдельная служба: доступ по числовому адресу может работать при ошибке имени.',visual=table(['Узел / параметр','Значение','Проверка'],[['Рабочее место','192.168.10.50/24','ipconfig /all'],['Сервер','192.168.10.20/24','ping по адресу — если ICMP разрешён'],['Имя','ufis-server → 192.168.10.20','Resolve-DnsName ufis-server'],['Прикладной порт','443 в учебном стенде','Test-NetConnection ... -Port 443']],'Примеры команд для Windows; адреса и порт заменяются параметрами разрешённого стенда.')),
C('Состав проверок персонала','Порядок: питание и линк → локальная конфигурация → адрес назначения и маршрут → имя → доступ к нужному порту → контрольная операция. Наблюдения записывают до изменения настроек.',
'Ping проверяет ответы ICMP в момент проверки. Его отказ возможен при фильтрации ICMP даже у исправного приложения. Успешный TCP-сеанс к порту показывает достижимость слушающего сервиса, но не вход, права или корректную запись. Поэтому завершаем контрольной прикладной операцией. Изменять VLAN, шлюз или межсетевые правила следует только в разрешённом объёме; необоснованная смена конфигурации способна расширить неисправность.'),
C('Разбор: адрес работает, имя неверно','Учебные данные: 192.168.10.20:443 доступен; ufis-server разрешается в старый 192.168.10.19; сервис по старому адресу недоступен. Проверяем запись DNS и используемый клиентом сервер имён.',
'На числовом адресе уже проверен нужный порт. Имя ведёт в другое место, поэтому следующий шаг — установить источник неправильного разрешения: запись на DNS-сервере, локальный файл или кэш. Исправление выполняют по порядку организации, затем повторяют разрешение имени, подключение по имени и прикладную операцию. Очистка кэша без исправления источника даст только временное или нулевое изменение.'),
C('Дубликат адреса и подтверждение восстановления','При подозрении на конфликт сравнивают назначенный адрес, источник настройки DHCP/статический, наблюдаемые MAC и журнал. После исправления проверяют стабильность соединения и целевую операцию.',
'Временно исчезнувшая ошибка ещё не доказывает устранение конфликта: второй узел может быть выключен. Документируем, кому принадлежит адрес, как исключено повторное назначение и какой диапазон выдаёт DHCP. Не назначаем случайный свободный на вид адрес из рабочей сети. Для лабораторной подходит изолированный стенд с заранее заданными адресами.')],
dict(prompt='Ping сервера успешен, но вход в ИС не работает. Какой вывод корректен?',options=['Вся система исправна','Необходимы проверки порта и прикладного сценария','Нужно сразу заменить сервер','DNS обязательно исправен'],correct=1,explanation='Ответ ICMP подтверждает ограниченное свойство IP-связности; доступность приложения, права и разрешение имени проверяются отдельно.'),
dict(task='Выберите причину, непосредственно подтверждаемую данными: «DNS» или «порт».',output='Введите DNS или порт; не делайте вывод о функции сохранения без её проверки.',variants=[
V('Старый адрес в имени','TCP 443 на 192.168.10.20 доступен. Имя ufis-server разрешается в .19; должно в .20.',[('Адрес .20','TCP 443 доступен'),('Имя','Получен .19'),('Сопоставление','Ожидается .20')],'DNS','Различие числового адреса и результата имени требует проверить источник разрешения. Это не доказательство дефекта аппаратной сети.',['dns','днс']),
V('Нет слушающего порта','Имя разрешается правильно в .20; ICMP разрешён и отвечает; TCP 443 не устанавливается, сервис остановлен.',[('DNS','Правильный .20'),('IP','ICMP ответил'),('Сервис','Остановлен, TCP 443 недоступен')],'Порт','Данные локализуют остановленный прикладной сервис на нужном порту. Запуск выполняется по регламенту, затем проверяется сквозной сценарий.',['порт'])]),'network')

T('documentation',5,'Документация на информационную систему',
'Какой комплект позволяет другому специалисту обслужить систему?',
'Новый техник видит сервер и кабели, но не знает, какой сервис нужен складу и кто согласует остановку. Соберём комплект, связывающий назначение, состав и действия.',[
C('Состав комплекта','Для эксплуатации нужны описание назначения и границ, паспорт, перечень состава, схемы, инструкции пользователя и персонала, порядок восстановления, регламенты и журнал изменений. Конкретный комплект задают договор и требования организации.',
'Название документа само по себе не обеспечивает полезность. Схема без идентификаторов не связывается с реальными устройствами; инструкция без проверки результата оставляет неопределённость. Описание функции объясняет, зачем существует сервис, паспорт даёт сжатые актуальные сведения, инструкция задаёт воспроизводимое действие. Для учебной работы мы собираем эксплуатационный комплект, не объявляя его универсальным нормативным составом.',
'Эксплуатационная документация — сведения и инструкции, необходимые для использования, обслуживания и восстановления системы.'),
C('Паспорт системы','Паспорт содержит назначение, границы, ответственных, состав и идентификаторы, размещение, зависимости, основные параметры, ссылки на схемы, обслуживание и восстановление. Секреты заменяют ссылкой на защищённое место хранения.',
'Пароль в общей таблице делает паспорт удобным только на первый взгляд: копии быстро расходятся и расширяют доступ. Нужна ссылка на процедуру получения разрешённых реквизитов. Идентификаторы связывают паспорт с маркировкой оборудования и схемой портов. Для каждого существенного параметра полезны источник и дата проверки; это эксплуатационная актуальность документа, а не служебная версия лекционного курса.',visual=table(['Раздел','Пример сведений','Как проверить'],[['Назначение','Учёт поступления и отпуска','Контрольная операция'],['Состав','SRV-01, SW-01, АРМ-01','Сверка с маркировкой'],['Связи','Порты и VLAN учебного стенда','Схема и конфигурация'],['Восстановление','Копия и порядок проверки','Учебное восстановление'],['Ответственность','Роль сопровождения','Установленный порядок связи']],'Паспорт — карта актуальных сведений, а не хранилище паролей.')),
C('Схемы и инструкции','Структурная схема показывает состав; функциональная — взаимодействие; схема подключений — порты и линии. Инструкция задаёт исходные условия, операции, ожидаемые результаты и точку остановки при отклонении.',
'Эти представления отвечают на разные вопросы и могут ссылаться друг на друга. Для замены патч-корда достаточно схемы портов и маркировки, но для восстановления базы нужна последовательность работы с копией и критерий целостности. Инструкция должна объяснить, что делать при отличающемся результате: продолжение по успешной ветви без свидетельств способно уничтожить полезные данные.'),
C('Разбор: найдено несоответствие паспорта','Учебный паспорт указывает SRV-01=.20; схема — .20; фактическая проверка разрешённого стенда показывает сервис на .30. В журнале есть согласованная смена адреса. Исправляем связанные сведения и проверяем ссылки.',
'Фактическое наблюдение ещё не разрешает немедленно менять настройку сервера обратно. Сначала выясняем основание изменения. Журнал показывает согласованную миграцию, значит устарела документация. Обновляем паспорт, схему, параметры контрольной команды и инструкцию, затем другой специалист повторяет проверку. Исправление только одной таблицы оставило бы противоречие в комплекте.'),
C('Проверка комплектности действием','Другой специалист должен найти устройство и его роль, определить допустимое действие, выполнить его на стенде и подтвердить результат. Неописанная зависимость или непонятный шаг — обнаруженный пробел комплекта.',
'Проверяем не количество страниц, а воспроизводимость. Выбираем конкретный сценарий: восстановление учебного сервиса из копии. Если отсутствуют версия приложения, порядок запуска или способ сопоставить документы, комплект не обеспечивает этот сценарий. Составляют перечень пробелов и дополняют нужные документы. Официальное принятие комплекта выполняется по установленным требованиям проекта.')],
dict(prompt='В паспорте и инструкции разные адреса сервера. Что сделать сначала?',options=['Вернуть сервер к адресу из паспорта','Установить актуальное состояние и основание изменения, затем согласовать документы','Удалить инструкцию','Оставить оба адреса без объяснения'],correct=1,explanation='Документ может устареть. Сначала сверяют фактическое состояние и согласованное изменение, затем актуализируют связанные части комплекта.'),
dict(task='Что требует исправления по подтверждённым данным: «документация» или «конфигурация»?',output='Введите одно слово; в условии явно указано согласованное целевое состояние.',variants=[
V('Согласованная миграция','Целевой адрес по согласованному изменению .30. Сервис реально на .30, паспорт всё ещё .20.',[('Цель','.30'),('Факт','.30'),('Паспорт','.20 — устарел')],'Документация','Сервис соответствует целевому состоянию. Обновить паспорт и связанные инструкции, не откатывать согласованную миграцию.',['документация']),
V('Неверная настройка','Целевой адрес .20, изменения не разрешались. Паспорт и схема .20. На стенде по ошибке задан .30.',[('Цель','.20'),('Документы','.20'),('Факт','.30 — расхождение')],'Конфигурация','На разрешённом стенде исправить ошибочную настройку по принятому порядку, проверить связь и функцию, зафиксировать устранение.',['конфигурация'])]),'systems')
